from pathlib import Path
p=Path('frontline.js');s=p.read_text(encoding='utf-8').replace("addCorpse('walker',e.x+Math.cos(angle)*30", "addCorpse(run.level>=5?'robot':'walker',e.x+Math.cos(angle)*30")
s=s.replace("zombie(xx,yy,'walker',.78,o.age+i,o.hit>0&&i===left-1);", "if(run.level>=5)drawAtlas(ctx,'robot',0,0,xx,yy,28,o.hit>0&&i===left-1);else zombie(xx,yy,'walker',.78,o.age+i,o.hit>0&&i===left-1);")
s=s.replace('围困丧尸 ${left}','围困敌人 ${left}')
p.write_text(s,encoding='utf-8')
p=Path('tests/frontline.test.cjs');s=p.read_text(encoding='utf-8').replace('thirteen missions contain eight non-boss routes and five distinct chapter bosses','twenty-six missions contain sixteen routes and ten distinct chapter bosses').replace('assert.equal(bosses,5);assert.equal(normals,8);for(let chapter=0;chapter<5;chapter++)','assert.equal(bosses,10);assert.equal(normals,16);for(let chapter=0;chapter<10;chapter++)')
s+='''
test('chapters six to ten spawn mechanical enemies, with additional elites progressively introduced',()=>{for(let level=5;level<10;level++){const r=new F.Run({level,seed:55});r.entities=[];r.spawnHorde(0,100,30,3);assert.ok(r.entities.every(o=>F.ROBOT_TYPES.includes(o.type)));assert.ok(r.entities.some(o=>o.type==='gunner'));assert.equal(r.entities.some(o=>o.type==='rocketeer'),level>=6);assert.equal(r.entities.some(o=>o.type==='shieldbot'),level>=7);assert.equal(r.entities.some(o=>o.type==='drone'),level>=8);}});
test('mechanical infantry fires visible delayed bullets which wound a soldier on contact',()=>{const r=empty();r.army=1;r.syncMembers();r.unit('robot',r.x,350,{speed:0,fireClock:.01});advance(r,.02);assert.ok(r.enemyBullets.length);assert.equal(r.members[0].hp,2);advance(r,1);assert.equal(r.members[0].hp,1);assert.equal(r.army,1);});
test('moving after hostile fire dodges its locked trajectory',()=>{const r=empty();r.army=1;r.syncMembers();r.unit('robot',r.x,350,{speed:0,fireClock:.01});advance(r,.02);r.move(326);advance(r,1.1);assert.equal(r.members[0].hp,2);});
test('frontline tank intercepts a hostile bullet before it reaches the squad',()=>{const r=empty();r.army=1;r.inventory=[{type:'mgTank',count:1}];r.deploy(0,106,300);advance(r,3.1);const tank=r.effects[0];r.enemyShot({x:r.x,y:450,type:'robot'},Math.PI/2,600,1);advance(r,.4);assert.equal(r.members[0].hp,2);assert.equal(tank.hp,tank.max-45);assert.equal(r.enemyBullets.length,0);});
test('EMP interrupts mechanical shooting and missiles telegraph before AoE',()=>{const r=empty();r.inventory=[{type:'emp',count:1}];r.deploy(0,106,330);advance(r,1.1);r.unit('robot',106,350,{speed:0,fireClock:.01});advance(r,.3);assert.equal(r.enemyBullets.length,0);r.effects=[];r.entities=[];r.unit('rocketeer',326,350,{speed:0,fireClock:.01});advance(r,.02);assert.ok(r.effects.some(e=>e.type==='enemyBlast'));assert.ok(r.members.every(m=>m.hp===2));advance(r,1.6);assert.ok(r.casualties>1);});
test('five mech bosses have distinct attack families and final victory only occurs in chapter ten',()=>{const kinds=[];for(let level=5;level<10;level++){const r=new F.Run({level});r.entities=[];r.nextWave=Infinity;r.shotClock=Infinity;r.bossSpawned=true;const boss=r.unit('giant',216,270,{attackTimer:0,pattern:0,phase:1,recover:0});r.bossStep(boss,.02);kinds.push(F.LEVELS[level].kind);assert.ok(r.effects.length||r.enemyBullets.length||r.entities.length>1);}assert.equal(new Set(kinds).size,5);const r=empty();r.stageId=12;r.level=4;r.completeStage();assert.equal(r.state,'cleared');r.state='playing';r.stageId=F.STAGES.length-1;r.level=9;r.completeStage();assert.equal(r.state,'won');});
test('robot spawn cap and hostile projectile lifetime bound crowded battle state',()=>{const r=new F.Run({level:9});r.entities=[];for(let i=0;i<50;i++)r.spawnRobots(0,100,50);assert.ok(r.entities.length<=44);r.entities=[];r.enemyShot({x:30,y:300,type:'robot'},-Math.PI/2,300);advance(r,4.1);assert.equal(r.enemyBullets.length,0);});
''';p.write_text(s,encoding='utf-8')
